package com.example.app05.application.service; import com.example.app05.domain.entity.Product; import com.example.app05.infrastructure.repository.ProductRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class ProductService { private final ProductRepository repository; public ProductService(ProductRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Product> list() { return repository.findAll(); } @Transactional public Product create(Product e) { return repository.save(e); } }
